import{_ as o,l as i,o as e,c as l,v as t,p as s,x as r,d as A,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"篮子 PCA 残差","description":"","frontmatter":{"title":"篮子 PCA 残差","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pca-residual-basket.md","filePath":"quant/pca-residual-basket.md","lastUpdated":1789023840000}'),d={name:"quant/pca-residual-basket.md"};function h(c,a,u,_,B,P){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="篮子-pca-残差" tabindex="-1">篮子 PCA 残差 <a class="header-anchor" href="#篮子-pca-残差" aria-label="Permalink to &quot;篮子 PCA 残差&quot;">​</a></h1><div class="epigraph"><p>在十到三十只事先限定的名字上做主成分，抽掉篮子内部的共同模式，交易正交补：这不是全市场统计套利的缩微版，因为因子的经济含义、秩的选择与容量约束都随篮子边界而变。</p><footer>—— 截面主成分见 Connor &amp; Korajczyk；残差交易框架见 Avellaneda &amp; Lee, Quantitative Finance, 2010；篮子边界使对象从市场因子变成局部共同趋势</footer></div><p><a href="/quant/pca-stat-arb">PCA 统计套利</a> 与 <a href="/quant/avellaneda-lee">Avellaneda–Lee</a> 的默认舞台是全市场（或大范围）股票：前 \\(K\\) 个主成分近似市场、行业、风格。本篇把同样的 SVD 接到<strong>预先指定的小篮子</strong>上：同一行业的核心股、同一产业链、同一指数分层里的一组可交易名字。此时第一主成分往往就是该篮子的局部「市场」，残差才是行业内相对价值。它补全的是全市场 PCA 放太大、\\(K\\) 又不够时把行业动量留在残差里的那条缝，也与 <a href="/quant/sector-rv">行业内相对价值</a> 共用经济对象、换一种正交化语言。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全市场 PCA 的 \\(K\\) 若取小，行业轮动进入残差，AL 的 s-score 会变成行业动量或反转，取决于符号。\\(K\\) 取大，又把可交易的相对价值洗掉，而且载荷在高维下不稳。篮子 PCA 的回答是：先用经济边界把 \\(N\\) 降到 8–30，再在篮子里取 \\(K=1\\) 或 \\(2\\)，让残差的含义变成「相对这组同伴的偏离」。问题立刻变成篮子怎么定。若篮子用形成期相关或距离来选，再在同一段样本上做 PCA 残差，多重检验与 GGR 选对是同一类——样本内共同因子被设计成很强，残差回归被设计成很好看。</p><p>可交易性是第二条约束。全市场残差策略可以在五千只里挑 \\(s\\) 最极端的几十只，分散看起来很好。篮子残差必须在这三十只里做多空，流动性差的特异腿无法被篮子外的名字替代。容量比全市场残差更窄，不是更宽：边界既限制了风险，也限制了分散。</p><h3 id="局部第一主成分不是市场指数" tabindex="-1">局部第一主成分不是市场指数 <a class="header-anchor" href="#局部第一主成分不是市场指数" aria-label="Permalink to &quot;局部第一主成分不是市场指数&quot;">​</a></h3><p>篮子内第一右奇异向量的权重通常集中在该组里市值或波动最大的几只，不必等于行业 ETF 的官方权重。用 ETF 当因子是 AL 的另一条路，冲击透明；用篮子 PCA 当因子，对冲要用成分股复制这一向量，换手与冲击发生在篮子内部。两者残差相关但不等同：ETF 含有篮子外的名字与申赎摩擦；PCA 因子每日随样本旋转。必须声明对冲工具是 ETF 还是复制组合，否则回测的冲击函数没有对象。</p><p><span class="marginnote">对篮子价格做 PCA 与对篮子收益做 PCA 仍不是同一策略。价格非平稳，第一主成分会变成一条随机趋势，残差可能像伪平稳。Avellaneda–Lee 的对象是收益或已构建的残差过程；小篮子同样遵守这条，不要因为 \\(N\\) 小就改用价格水平。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>形成期冻结篮子名单（经济分类、指数成分、或事先写死的核心对手盘），用收益矩阵 \\(R_{T\\times N}\\) 做 SVD，取 \\(K\\)。\\(K\\) 的默认在小 \\(N\\) 上往往是 1：再取第二、第三根很容易是噪声。解释方差阈值在 \\(N=15\\) 时会把噪声根抬进来，不如固定 \\(K=1\\)，让第一因子的方差变、个数不变。个股残差 \\(u_{it}=r_{it}-\\hat\\beta_i^\\top F_t\\)，再对 \\(u\\) 估 OU 或滚动 Z-score，在篮子内做美元中性或多空使 \\(\\sum w_i\\hat\\beta_i\\approx 0\\)。</p><p>对冲比即载荷。样本外 \\(F_t\\) 有两种接法：用形成期载荷对样本外收益投影（冻结载荷），或滚动重估。冻结更可复制、对断裂更迟钝；滚动更跟得上权重变化，但要对齐符号，并禁止在重估日用跳变残差开仓。这与 <a href="/quant/hedge-ratio-break">时变对冲比断裂</a> 同一纪律：载荷跳应视为事件，先平再估。</p> \\[u_{it}=r_{it}-\\sum_{k=1}^{K}\\hat\\beta_{ik}F_{kt},\\qquad w^\\top\\hat\\beta_{\\cdot k}=0\\ \\ (k=1,\\ldots,K). \\]<p>中性是对篮子因子，不是对全市场。篮子相对市场仍有净 beta，需要在组合层再对冲指数，还是接受这笔行业暴露，必须写清。许多「行业中性」失败，是因为只在篮子内中性、忘了篮子本身可以整体被做多。</p><h3 id="与协整篮子、距离配对的对照" tabindex="-1">与协整篮子、距离配对的对照 <a class="header-anchor" href="#与协整篮子、距离配对的对照" aria-label="Permalink to &quot;与协整篮子、距离配对的对照&quot;">​</a></h3><p>Johansen 在同一小篮子上估秩，寻求 \\(I(0)\\) 线性组合，见 <a href="/quant/coint-rank">协整秩选择</a>。PCA 残差不要求残差 \\(I(0)\\)，只要求共同方差被抽掉后剩下的截面有短持有负自相关。前者是长期关系，后者是短期流动性。可以先用协整筛「这篮子配不配做水平组合」，再用 PCA 残差做短持有——但两层都在同一 \\(N\\) 上估，样本内会极好。更干净的是：篮子由经济名单冻结，PCA 只做交易期信号，不做二次选股。</p><p>距离法在篮子里两两配对，是 \\(N(N-1)/2\\) 条价差；篮子 PCA 是 \\(N\\) 条残差共享 \\(K\\) 个因子。后者自动处理多边关系（A 相对 B 与 C 同时贵），前者会开出互相矛盾的对。小篮子里 PCA 往往比穷尽配对更少内部对冲冲突，这是改用残差的工程理由，不是统计上 PCA 比协整更真。</p><p><span class="marginnote">\\(N\\) 太小（三五只）时第一主成分不稳定，一只停牌就会旋转载荷。此时用行业 ETF 当单一因子更诚实，残差退化为相对 ETF 的回归，接近经典的行业相对价值。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>篮子内共同模式来自行业消息、共同客户、共同做市商库存、指数同时被买卖。抽掉它，剩下的是公司特异冲击与暂时的相对定价错误。短持有多空是在篮子内部供给流动性：买被错杀的、卖被炒高的，赌同伴会把相对价格拉回。若冲击来自永久的相对基本面（一只被收购、一只商誉爆雷），残差不回归，PCA 不会比配对更早告诉你——第一主成分可能被那只异常股污染，把断裂写成「因子」，让其他名字的残差全部歪掉。这是小样本 PCA 特有的脆弱：全市场里一只股票很难主导第一主成分，十五只里可以。</p><p>拥挤同样局部化。做同一行业相对价值的账户，残差相关性高于全市场 AL 的「看起来正交」。2007 年类事件在行业篮子里可以表现为：局部第一因子剧烈、残差同步走扩。压力测试应在篮子层做残差相关上升，而不是引用全市场 AL 的分散数字。</p><h3 id="容量写在特异腿上" tabindex="-1">容量写在特异腿上 <a class="header-anchor" href="#容量写在特异腿上" aria-label="Permalink to &quot;容量写在特异腿上&quot;">​</a></h3><p>中性化后仍要买卖残差最大的那些名字，它们往往是篮子里流动性较差、借券较紧的。名义扩张首先撞上这些腿的 ADV，而不是行业 ETF 的深度。用 ETF 对冲共同因子、用成分股交易残差，可以把共同腿的冲击移到 ETF 上，这通常优于在成分股上复制主成分。代价是残差定义与对冲工具不一致，出现基差。应在成本后比较「复制因子」与「ETF 因子」，而不是比较残差方差。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用形成期 SSD 或相关选篮子再在同一窗口做 PCA 并报告夏普。不要把全市场 AL 的 \\(K\\) 选择准则（解释方差 55% 之类）原样搬到 \\(N=12\\) 的篮子。不要对价格水平做 PCA 还引用 Quantitative Finance 2010。成分股调整日应视为断裂：名单变了，因子的经济对象变了，先平仓。</p><p>A 股行业分类与可融名单重叠后，篮子可能只剩能做多的一侧，残差空头缺腿。涨跌停会让一两只板股票主导协方差，载荷扭曲，形成期应截尾或用稳健 PCA。与 <a href="/quant/industry-neutral">行业中性</a> 的差别：行业中性是因子组合的约束；篮子 PCA 残差是在行业内部制造可交易的正交补。一个是风险控制，一个是 alpha 构造，可以同时用，但不是同一按钮。</p><p><span class="marginnote">Connor–Korajczyk 的渐近主成分针对 \\(N\\) 大、\\(T\\) 固定一类设定。\\(N=20\\) 时没有大截面渐近给你撑腰，载荷标准误要用 bootstrap 或简单的样本分割来看稳不稳，不能把全市场文献的 \\(K\\) 一致性定理写进小篮子的规格书。</span></p>',27)),(e(),s(p,null,{default:r(()=>[E(n,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20TD%0A%20%20UN%5B%22%E7%BB%8F%E6%B5%8E%E5%90%8D%E5%8D%95%E5%86%BB%E7%BB%93%20N%E2%89%888-30%22%5D%20--%3E%20SVD%5B%22%E7%AF%AE%E5%AD%90%E6%94%B6%E7%9B%8A%20SVD%22%5D%0A%20%20SVD%20--%3E%20F%5B%22K%3D1%20%E6%88%96%202%20%E5%B1%80%E9%83%A8%E5%9B%A0%E5%AD%90%22%5D%0A%20%20SVD%20--%3E%20U%5B%22%E6%AE%8B%E5%B7%AE%20u%22%5D%0A%20%20ETF%5B%22%E5%8F%AF%E9%80%89%3A%20%E8%A1%8C%E4%B8%9A%20ETF%20%E4%BD%9C%20F%22%5D%20--%3E%20U%0A%20%20U%20--%3E%20SIG%5B%22OU%20%2F%20Z-score%20%E7%AF%AE%E5%AD%90%E5%86%85%E5%A4%9A%E7%A9%BA%22%5D%0A%20%20SIG%20--%3E%20HEDGE%5B%22%E5%AF%B9%20F%20%E4%B8%AD%E6%80%A7%3B%20%E7%BB%84%E5%90%88%E5%B1%82%E6%98%AF%E5%90%A6%E5%AF%B9%E5%86%B2%E6%8C%87%E6%95%B0%22%5D%0A%20%20HEDGE%20--%3E%20CAP%5B%22%E5%AE%B9%E9%87%8F%3A%20%E7%89%B9%E5%BC%82%E8%85%BF%20ADV%20%E4%B8%8E%E5%80%9F%E5%88%B8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>篮子 PCA 残差在预先限定的小名单上抽局部共同因子，交易正交补；对象是行业内相对价值，不是全市场 AL 的缩微。</li><li>\\(K\\) 宜固定且小；篮子须经济冻结，不能用同一窗口的距离再选一轮。</li><li>局部第一主成分不等于行业 ETF，对冲工具与残差定义必须一致或显式承担基差。</li><li>小 \\(N\\) 下单只异常股可以污染因子；容量约束在特异腿，不在行业指数深度。</li><li>出处：Connor and Korajczyk；Avellaneda and Lee, <em>Quantitative Finance</em>, 2010；对照 <a href="/quant/pca-stat-arb">PCA 统计套利</a> 与 <a href="/quant/sector-rv">行业内相对价值</a>。</li></ul>',2))])}const F=o(d,[["render",h]]);export{m as __pageData,F as default};
